import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[] suffix = a.clone(); // suffix[i] = min(a[i..n-1])
        for (int i = n - 2; i >= 0; i--) suffix[i] = Math.min(suffix[i], suffix[i + 1]);
        long largest = a[0];
        int answer = 0;
        for (int i = 0; i + 1 < n; i++) {
            largest = Math.max(largest, a[i]);
            if (largest <= suffix[i + 1]) answer++; // no inversion across the cut
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	a := make([]int64, n)
	for i := range a {
		sc.Scan()
		a[i], _ = strconv.ParseInt(sc.Text(), 10, 64)
	}
	suffix := append([]int64(nil), a...) // suffix[i] = min(a[i..n-1])
	for i := n - 2; i >= 0; i-- {
		suffix[i] = min(suffix[i], suffix[i+1])
	}
	largest := a[0]
	answer := 0
	for i := 0; i+1 < n; i++ {
		largest = max(largest, a[i])
		if largest <= suffix[i+1] { // no inversion across the cut
			answer++
		}
	}
	fmt.Println(answer)
}
